  const before = await evaluate("(() => { const list = document.querySelector('ul.inbox-scroll'); const row = document.querySelectorAll('.inbox-row')[8]; row.focus(); list.scrollTop = Math.min(170, list.scrollHeight - list.clientHeight); return {id:row.getAttribute('data-test'),scrollTop:list.scrollTop,top:row.getBoundingClientRect().top}; })()");
