const pages=await(await fetch('http://'+new URL(state.debug_url).host+'/json/list')).json();
const page=pages.find(p=>p.type==='page'&&p.url.startsWith('http://127.0.0.1:5173/'));
if(!page)throw Error('No synthetic preview');const ws=new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r,j)=>{ws.addEventListener('open',r,{once:true});ws.addEventListener('error',j,{once:true});});
let id=0;const waiting=new Map();ws.addEventListener('message',e=>{const x=JSON.parse(e.data),p=waiting.get(x.id);if(!p)return;waiting.delete(x.id);clearTimeout(p.timer);x.error?p.reject(Error(JSON.stringify(x.error))):p.resolve(x.result);});
function cmd(method,params={}){return new Promise((resolve,reject)=>{const n=++id;const timer=setTimeout(()=>{waiting.delete(n);reject(Error('Timeout '+method));},10000);waiting.set(n,{resolve,reject,timer});ws.send(JSON.stringify({id:n,method,params}));});}
async function js(expression){const x=await cmd('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(x.exceptionDetails)throw Error(JSON.stringify(x.exceptionDetails));return x.result.value;}
const tick=()=>js('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');
async function click(sel){await js(`(()=>{const e=document.querySelector(${JSON.stringify(sel)});if(!e)throw Error('Missing '+${JSON.stringify(sel)});e.focus();e.click();})()`);await tick();}
